function renderInspector(){const s=state.streams.find(x=>x.stream_id===state.selected);$('inspector-empty').classList.toggle('hidden',!!s);$('inspector-content').classList.toggle('hidden',!s);if(!s){txt('inspector-title','选择一个流');txt('inspector-pill','未选择');return;}txt('inspector-title',s.stream_id);txt('inspector-pill',(s.publish_state||s.state||'idle').toUpperCase());$('inspector-pill').className=`pill ${s.publish_state==='connected'||s.frames_received?'on':'muted'}`;const previewBox=document.querySelector('.fake-preview');let previewImage=$('preview-image');let previewFallback=$('preview-image-fallback');if(previewBox&&!previewImage){previewBox.insertAdjacentHTML('afterbegin','<img id="preview-image" class="stream-preview-image" alt="视频流现场画面"><span id="preview-image-fallback" class="preview-image-fallback hidden">现场画面暂不可用</span>');previewImage=$('preview-image');previewFallback=$('preview-image-fallback');}if(previewImage){previewImage.classList.remove('hidden');previewImage.alt=`${s.stream_id}视频流现场画面`;previewImage.src=STREAM_PREVIEW_IMAGES[state.streams.indexOf(s)%STREAM_PREVIEW_IMAGES.length];previewImage.onerror=()=>{previewImage.classList.add('hidden');previewFallback?.classList.remove('hidden');};if(previewFallback)previewFallback.classList.add('hidden');}$('yolo-toggle').checked=!!s.yolo_enabled;$('confidence').value=s.confidence??.25;txt('confidence-value',Number(s.confidence??.25).toFixed(2));$('max-fps').value=s.max_fps??20;txt('fps-value',s.max_fps??20);txt('preview-label',s.frames_received?(s.yolo_enabled?'YOLO OVERLAY · LIVE':'RAW STREAM · LIVE'):'WAITING FOR FRAMES');txt('preview-fps',`${s.max_fps??20} FPS CAP`);const p=state.playback||{};const entry=(name)=>p[name]||{};const whep=entry('whep'),hls=entry('llhls'),rtsp=entry('rtsp');txt('whep-state',whep.available?'可用':'等待连接');txt('hls-state',hls.available?'可回退':'未就绪');txt('rtsp-state','诊断通道');[['whep-url',whep.url],['hls-url',hls.url],['rtsp-url',rtsp.url]].forEach(([id,url])=>{const a=$(id);if(a){a.href=url||'#';a.textContent=url||'地址不可用';a.classList.toggle('disabled',!url);}});const detections=state.detections?.detections||[];$('stream-detections').innerHTML=detections.length?detections.map(d=>`<div class="detection-row"><b>${esc(d.label||d.class_name||'object')}</b><span>${Number(d.confidence||0).toFixed(2)} · ${esc(JSON.stringify(d.bbox||d.box||''))}</span><em>WebSocket</em></div>`).join(''):(s.frames_received&&s.yolo_enabled&&!state.demo?'<div class="detection-empty">等待检测元数据…</div>':'<div class="detection-empty">当前没有结构化检测结果</div>');}
async function loadLiveStream(stream){if(state.detectionSocket){state.detectionSocket.close();state.detectionSocket=null;}state.playback=null;state.detections=null;try{const response=await fetch(`/api/streams/${encodeURIComponent(stream.stream_id)}/playback`);if(response.ok)state.playback=await response.json();}catch(e){state.playback={};}renderInspector();if(stream.yolo_enabled){const wsUrl=`${location.protocol==='https:'?'wss':'ws'}://${location.host}/api/streams/${encodeURIComponent(stream.stream_id)}/detections`;try{const socket=new WebSocket(wsUrl);state.detectionSocket=socket;socket.onmessage=e=>{try{state.detections=JSON.parse(e.data);renderInspector();}catch(_){}};socket.onclose=()=>{if(state.detectionSocket===socket)state.detectionSocket=null;};}catch(_){}}}
async function refreshLiveStreams(){try{const response=await fetch('/api/streams');if(!response.ok)throw new Error(`HTTP ${response.status}`);const data=await response.json();state.streams=data.map(s=>({...s,source:s.source||s.publish_url||'服务端流',frames_received:s.frames_received||0,tag:s.model?.model_id||'服务端'}));if(!state.selected&&state.streams[0])state.selected=state.streams[0].stream_id;renderOverview();renderStreams();renderStreamBindings();renderInspector();if(state.selected)await loadLiveStream(state.streams.find(s=>s.stream_id===state.selected));txt('service-state','Live API 已连接');}catch(e){txt('service-state',`Live API 不可用 · ${e.message}`);}}
function renderAlerts(){const list=state.alertFilter==='all'?MOCK.alerts:MOCK.alerts.filter(a=>a[5]===state.alertFilter);$('alert-table').innerHTML=list.map(a=>{const index=MOCK.alerts.indexOf(a),v=VERIFICATION_MOCK[index%VERIFICATION_MOCK.length],review=v[0]==='confirmed'?'确认':v[0]==='false_positive'?'疑似误报':v[0]==='failed'?'失败':'未复核';return `<button class="alert-row" data-alert-index="${index}"><span class="alert-thumb"><img src="${a[7]||''}" alt="${esc(a[0])}证据" onerror="this.parentElement.classList.add('missing');this.remove()"></span><span class="alert-title"><i class="severity-dot ${a[5]}"></i><b>${esc(a[0])}</b><small>${a[4]}</small></span><span><b>${esc(a[1])}</b><small>${esc(a[2])}</small></span><span class="mono">${a[3]}</span><span class="state-chip ${a[6]==='待确认'?'pending':a[6]==='处理中'?'working':'done'}">${a[6]}</span><span class="alert-action"><span class="verification-chip">复核：${review}</span><span class="row-arrow" aria-hidden="true">→</span></span></button>`;}).join('');document.querySelectorAll('.alert-row').forEach(x=>x.onclick=()=>{const index=Number(x.dataset.alertIndex);const targetIndex=MOCK.pushTargets.findIndex(t=>t[4]);if(targetIndex>=0)simulatePush(targetIndex,index);openAlert(index);});}
