function renderPushTargets(){txt('nav-push-count',String(MOCK.pushTargets.filter(t=>t[4]).length).padStart(2,'0'));$('push-table').innerHTML=MOCK.pushTargets.map((t,i)=>`<div class="push-row"><b>${esc(t[0])}</b><span class="push-type">${esc(t[1])}</span><code>${esc(t[2])}</code><span class="state-chip ${t[4]?'done':'muted'}">${t[3]}</span><span class="push-actions"><button class="text-btn" data-push-test="${i}">测试推送</button><button class="icon-btn" data-push-toggle="${i}">${t[4]?'停用':'启用'}</button></span></div>`).join('');document.querySelectorAll('[data-push-test]').forEach(x=>x.onclick=()=>simulatePush(Number(x.dataset.pushTest)));document.querySelectorAll('[data-push-toggle]').forEach(x=>x.onclick=()=>{const t=MOCK.pushTargets[Number(x.dataset.pushToggle)];t[4]=!t[4];t[3]=t[4]?'启用':'停用';renderPushTargets();});}
