// M11-T09 Live API adapter.  Read-only alert snapshots are available to both
// clients; disposition mutations require an admin token and operator header.
async function refreshLiveAlerts(){try{const h=window.ADMIN_TOKEN?{'X-Admin-Token':window.ADMIN_TOKEN}:{};const r=await fetch('/api/alerts',{headers:h});if(!r.ok)throw Error(`HTTP ${r.status}`);const rows=(await r.json()).events||[];state.liveAlerts=rows;MOCK.alerts=rows.map(e=>[e.ruleId||e.eventId,e.sourceId||'',e.subjectKey||'',new Date((e.confirmedAtUs||0)/1000).toLocaleTimeString('zh-CN',{hour12:false}),e.notifySeverity||e.severity||'一般',String(e.severity||'MINOR').toLowerCase(),(e.disposition||{}).status||'OPEN',((e.evidence||{}).snapshotUri||'')]);renderAlerts();renderOverview();}catch(_){}}
async function submitLiveDisposition(eventId,status){const path=status==='FALSE_POSITIVE'?'false-positive':status==='ACKNOWLEDGED'?'acknowledge':'close';const h={'Content-Type':'application/json'};if(window.ADMIN_TOKEN)h['X-Admin-Token']=window.ADMIN_TOKEN;if(window.OPERATOR_ID)h['X-Operator-Id']=window.OPERATOR_ID;const r=await fetch(`/api/alerts/${encodeURIComponent(eventId)}/${path}`,{method:'POST',headers:h,body:'{}'});if(!r.ok)throw Error(`HTTP ${r.status}`);await refreshLiveAlerts();}
async function requestLiveVerification(eventId,image){const h={'Content-Type':'application/json'};if(window.ADMIN_TOKEN)h['X-Admin-Token']=window.ADMIN_TOKEN;if(window.OPERATOR_ID)h['X-Operator-Id']=window.OPERATOR_ID;const r=await fetch(`/api/alerts/${encodeURIComponent(eventId)}/verification`,{method:'POST',headers:h,body:JSON.stringify({image:image||null})});const body=await r.json().catch(()=>({}));if(!r.ok)throw Error(body?.detail?.message||`HTTP ${r.status}`);return body;}
async function syncLiveVerificationConfig(){if(state.demo)return;const h={'Content-Type':'application/json'};if(window.ADMIN_TOKEN)h['X-Admin-Token']=window.ADMIN_TOKEN;if(window.OPERATOR_ID)h['X-Operator-Id']=window.OPERATOR_ID;await fetch('/api/verification/config',{method:'POST',headers:h,body:JSON.stringify({enabled:!!$('verification-enabled')?.checked,imageEgressAuthorized:!!$('verification-image-consent')?.checked,dailyLimit:Number($('verification-limit')?.value||100),modelId:$('verification-model')?.value||'',providerConfigured:!!$('verification-key')?.value&&$('verification-key').value!=='••••••••••••'})});}
